import { readFileSync } from "node:fs";
import { defineConfig } from "vitest/config";
import { cloudflareTest } from "@cloudflare/vitest-pool-workers";

// The fixture key is regenerated by test/fixtures/make.sh, so read it at run time.
const NOTE_PUBKEY = readFileSync(new URL("./test/fixtures/key.pub", import.meta.url), "utf8").trim();

const WEBHOOK_SECRET = "test-webhook-secret";

export default defineConfig({
  plugins: [
    cloudflareTest({
      wrangler: { configPath: "./wrangler.toml" },
      miniflare: { bindings: { NOTE_PUBKEY, WEBHOOK_SECRET } },
    }),
  ],
});
